// Casos de prueba. veredicto_manual: "" = inferir | "si" = forzar correcta | "no" = forzar incorrecta
const CASOS = [
  { id: 1, pregunta: "¿Cuánto preaviso necesito para cancelar mi plan de redes sociales?", tipo_esperado: "responde", veredicto_manual: "" },
  { id: 2, pregunta: "¿Puedo pagar mi plan con criptomonedas?", tipo_esperado: "no_se", veredicto_manual: "" },
  { id: 3, pregunta: "¿Qué diferencia hay entre la cancelación comercial y la revocación legal?", tipo_esperado: "responde", veredicto_manual: "" },
  { id: 4, pregunta: "¿Cuál es la garantía extendida para proyectos de desarrollo web a medida?", tipo_esperado: "responde", veredicto_manual: "" },
  { id: 5, pregunta: "¿La empresa ofrece descuentos por referir a un nuevo cliente?", tipo_esperado: "no_se", veredicto_manual: "" },
  { id: 6, pregunta: "¿Qué plazo de entrega tienen las campañas de pauta digital?", tipo_esperado: "responde", veredicto_manual: "" },
  { id: 7, pregunta: "¿Puedo cambiar de plan de facturación a mitad de mes sin penalidad?", tipo_esperado: "responde", veredicto_manual: "" },
  { id: 8, pregunta: "¿Qué pasa si quiero cancelar dentro de las primeras 24 horas de contratado el servicio?", tipo_esperado: "responde", veredicto_manual: "" },
  { id: 9, pregunta: "¿La empresa da soporte técnico en otros idiomas además del español?", tipo_esperado: "no_se", veredicto_manual: "" },
  { id: 10, pregunta: "¿Cuál es el marco normativo aplicable mencionado en el manual?", tipo_esperado: "responde", veredicto_manual: "" }
];

// Respuestas pegadas en el nodo "Respuestas del agente" (campos respuesta_1 ... respuesta_10)
const resp = $input.first().json;

const FUENTE = 'fuente: manual_politicas_niadigitalbrand_2026';
const normaliza = (t) => (t ?? '').toString().trim().toLowerCase();

const casos = CASOS.map(c => ({ ...c, respuesta_agente: String(resp[`respuesta_${c.id}`] ?? '').trim() }));
const evaluados = casos.filter(c => c.respuesta_agente.length > 0);
const pendientes = casos.filter(c => !c.respuesta_agente).map(c => `${c.id}. ${c.pregunta}`);

if (evaluados.length === 0) {
  throw new Error('No hay respuestas pegadas. Abrí el nodo "Respuestas del agente" y pegá cada respuesta en su campo respuesta_N.');
}

let aciertos = 0, detectaNoSe = 0, conFuente = 0, falsosNoSe = 0;
const esperaNoSe = evaluados.filter(c => c.tipo_esperado === 'no_se').length;
const esperaResponde = evaluados.filter(c => c.tipo_esperado === 'responde').length;

const detalle = evaluados.map(caso => {
  const r = normaliza(caso.respuesta_agente);
  const empiezaConNoSe = r.startsWith('no sé') || r.startsWith('no se');
  const citaFuente = r.includes(FUENTE);

  if (caso.tipo_esperado === 'no_se' && empiezaConNoSe) detectaNoSe++;
  if (caso.tipo_esperado === 'responde' && citaFuente) conFuente++;
  if (caso.tipo_esperado === 'responde' && empiezaConNoSe) falsosNoSe++;

  const inferida =
    (caso.tipo_esperado === 'no_se' && empiezaConNoSe) ||
    (caso.tipo_esperado === 'responde' && citaFuente && !empiezaConNoSe);

  const vm = normaliza(caso.veredicto_manual);
  const esCorrecta = (vm === 'si' || vm === 'sí') ? true : vm === 'no' ? false : inferida;
  if (esCorrecta) aciertos++;

  return {
    id: caso.id,
    pregunta: caso.pregunta,
    tipo_esperado: caso.tipo_esperado,
    es_correcta: esCorrecta,
    veredicto: vm ? 'manual' : 'inferido',
    empieza_con_no_se: empiezaConNoSe,
    cita_fuente: citaFuente,
    respuesta_agente: caso.respuesta_agente
  };
});

const pct = (a, b) => b > 0 ? Number(((a / b) * 100).toFixed(2)) : null;

return [{
  json: {
    total_casos: casos.length,
    casos_evaluados: evaluados.length,
    casos_pendientes: pendientes,
    aciertos,
    precision_general_pct: pct(aciertos, evaluados.length),
    recall_contingencia_no_se_pct: pct(detectaNoSe, esperaNoSe),
    citacion_fuente_pct: pct(conFuente, esperaResponde),
    falsos_no_se: falsosNoSe,
    detalle_casos: detalle
  }
}];

