// Evalúa la salida del agente y prepara los datos para registro y respuesta.
const FUENTE = 'Fuente: Manual_Politicas_NiaDigitalBrand_2026';
const agente = $input.first().json;

// Lee un nodo sin romper el flujo si no existe o no se ejecutó
function leer(nombre) {
  try { return $(nombre).first().json; } catch (e) { return null; }
}

const chat = leer('Chat cliente');                         // chat de pruebas de n8n
const tg = leer('Receptor audio');                         // mensaje de Telegram
const whisper = leer('Whisper - Convertir audio a texto'); // transcripción del audio

// Pregunta del cliente: chat de n8n, audio transcrito o texto de Telegram
const chatInput = chat?.chatInput ?? whisper?.text ?? tg?.message?.text ?? '';
const chatId = tg?.message?.chat?.id ?? null;
const sessionId = chat?.sessionId ?? (chatId ? String(chatId) : '');

let output = String(agente.output ?? '').trim();
const lower = output.toLowerCase();

let tipo = 'responde';
if (!output) {
  tipo = 'sin_respuesta';
} else if (lower.startsWith('no sé') || lower.startsWith('no se') || lower.includes('no especifica esta condición')) {
  tipo = 'no_se';
}

if (output && !output.includes(FUENTE)) {
  output = `${output}\n\n${FUENTE}`;
}

return [{
  json: {
    tieneRespuesta: output.length > 0,
    tipo,
    output,
    chatInput,
    sessionId,
    chatId,
    origen: chat ? 'chat_n8n' : (whisper?.text ? 'telegram_audio' : 'telegram_texto')
  }
}];

