// Une Telegram, WhatsApp (Whapi) y Slack en un solo formato.
// Funciona con nodos con o sin sufijo (Receptor Telegram1, Whisper...3, etc.)

// Lee el primer nodo que exista y se haya ejecutado
function leer(base) {
  for (const sufijo of ['', '1', '2', '3', '4', '5']) {
    try { return $(base + sufijo).first().json; } catch (e) { /* no existe o no se ejecutó */ }
  }
  return null;
}

const entrada = $input.first().json;

// 1) Identificar el mensaje original: si la entrada ES el trigger, usarlo directo;
//    si viene de Whisper (audio), buscar el trigger por nombre.
let tg = entrada.message ? entrada : null;
let wa = entrada.body?.messages ? entrada : null;
// Slack Trigger: el evento puede venir directo o dentro de "event"
const eventoSlack = entrada.event ?? entrada;
let slack = (eventoSlack?.channel && eventoSlack?.ts && eventoSlack?.type) ? eventoSlack : null;
const vieneDeWhisper = !tg && !wa && !slack;

if (vieneDeWhisper) {
  tg = leer('Receptor Telegram');
  wa = tg ? null : leer('Entrada WhatsApp');
}

// Ignorar mensajes publicados por bots (incluido el propio asistente) para evitar bucles
if (slack && (slack.bot_id || slack.subtype === 'bot_message')) {
  return [];
}

// 2) Texto transcrito (solo si la entrada viene de Whisper)
const transcripcion = vieneDeWhisper
  ? String(entrada.text ?? entrada.data?.text ?? '').trim()
  : '';
const errorTranscripcion = vieneDeWhisper && !transcripcion
  ? (entrada.error?.message ?? entrada.error ?? 'Whisper no devolvió texto')
  : null;

// 3) Armar el mensaje unificado
let canal = 'slack', chat_id = '', tel = '', nombre = '', pregunta = '', esAudio = false;

if (tg?.message) {
  const m = tg.message;
  canal = 'telegram';
  chat_id = String(m.chat?.id ?? '');
  tel = String(m.from?.id ?? '');
  nombre = [m.from?.first_name, m.from?.last_name].filter(Boolean).join(' ');
  esAudio = !!(m.voice || m.audio);
  pregunta = esAudio ? transcripcion : (m.text ?? m.caption ?? '');

} else if (wa?.body?.messages?.length) {
  const m = wa.body.messages[0];
  canal = 'whatsapp';
  chat_id = String(m.chat_id ?? '');
  tel = String(m.from ?? '');
  nombre = m.from_name ?? '';
  esAudio = ['voice', 'audio'].includes(m.type);
  pregunta = esAudio
    ? transcripcion
    : (m.text?.body ?? m.image?.caption ?? m.video?.caption ?? m.document?.caption ?? '');

} else if (slack) {
  canal = 'slack';
  chat_id = String(slack.channel ?? '');
  tel = String(slack.user ?? '');
  nombre = slack.user_profile?.real_name ?? slack.user_profile?.display_name ?? '';
  // Quita la mención al bot (<@U123ABC>) del inicio del texto
  pregunta = String(slack.text ?? '').replace(/<@[A-Z0-9]+>/g, '').trim();
}

return [{
  json: {
    canal,
    chat_id,
    tel,
    nombre,
    pregunta: String(pregunta).trim(),
    es_audio: esAudio,
    error_transcripcion: errorTranscripcion,
    session_id: `${canal}:${chat_id}`
  }
}];

// Normaliza el binario del audio (Telegram o WhatsApp) para Whisper
for (const item of $input.all()) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}
return $input.all();

